def solve_m(m):
    divisors = get_divisors(m)
    n = len(divisors)

    # Necessary condition: Sum of all divisors must be a perfect square
    total_sum = sum(divisors)
    if not is_perfect_square(total_sum):
        return False, None, "Sum of divisors is not a perfect square."

